def check(output: str, ctx: dict) -> bool:
    question = ctx['question'].lower()
    sql = extract_sql(output).lower()
    mentioned_columns = [col.lower() for table, cols in ctx['schema'].items() for col in cols if col.lower() in question]
    return all(col in sql for col in mentioned_columns)

def check(output: str, ctx: dict) -> bool:
    if 'distinct' in ctx['question'].lower():
        sql = extract_sql(output).lower()
        return 'distinct' in sql
    return True

def check(output: str, ctx: dict) -> bool:
    if 'where' in ctx['question'].lower() or 'filter' in ctx['question'].lower():
        sql = extract_sql(output).lower()
        return 'where' in sql
    return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    table_mentions = [table for table in ctx['schema'] if table.lower() in sql]
    if len(table_mentions) > 1:
        return ' as ' in sql or any(f'{table.lower()}.' in sql for table in table_mentions)
    return True

