def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    for table, columns in ctx['schema'].items():
        if any(col in sql and 'distinct' in sql for col in columns):
            return False
    return True

def check(output: str, ctx: dict) -> bool:
    if '*' in extract_sql(output):
        return 'all' in ctx['question'].lower() or 'everything' in ctx['question'].lower()
    return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    relevant_tables = [table.lower() for table in ctx['schema'] if table.lower() in ctx['question'].lower()]
    for table in ctx['schema']:
        if table.lower() in sql and table.lower() not in relevant_tables:
            return False
    return True

def check(output: str, ctx: dict) -> bool:
    question = ctx['question'].lower()
    if any(op in question for op in ['greater than', 'less than', 'more than', 'fewer than']):
        sql = extract_sql(output).lower()
        return any(op in sql for op in ['>', '<', '>=', '<='])
    return True

