def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    schema_items = [item.lower() for table in ctx['schema'] for item in ctx['schema'][table]]
    return all(item in schema_items for item in re.findall(r'[a-z_]+', sql))

def check(output: str, ctx: dict) -> bool:
