def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    if 'group by' in sql:
        return 'having' in sql or not 'where' in sql
    return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    aliases = re.findall(r'as\s+([a-z_]+)', sql)
    return all(alias in sql for alias in aliases)

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    return sql == extract_sql(output)

def check(output: str, ctx: dict) -> bool:
    if any(word in ctx['question'].lower() for word in ['difference', 'sum', 'product']):
        return any(func in extract_sql(output).lower() for func in ['sum(', '-', '*', '/'])
    return True

def check(output: str, ctx: dict) -> bool:
    if 'null' in ctx['question'].lower():
        return 'is null' in extract_sql(output).lower() or 'is not null' in extract_sql(output).lower()
    return True
